<script>
(function(){
  "use strict";

  // ---------- generic emboss / relief helpers ----------

  function embossText(ctx, text, x, y, font, mainColor, shadowColor, highlightColor, depth){
    ctx.font = font;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = shadowColor;
    ctx.fillText(text, x + depth, y + depth);
    ctx.fillStyle = highlightColor;
    ctx.fillText(text, x - depth, y - depth);
    ctx.fillStyle = mainColor;
    ctx.fillText(text, x, y);
  }

  function embossStroke(ctx, pathFn, lineWidth, mainColor, shadowColor, highlightColor, depth){
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.save();
    ctx.translate(depth, depth);
    pathFn();
    ctx.strokeStyle = shadowColor;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.translate(-depth, -depth);
    pathFn();
    ctx.strokeStyle = highlightColor;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
    ctx.restore();

    pathFn();
    ctx.strokeStyle = mainColor;
    ctx.lineWidth = lineWidth * 0.7;
    ctx.stroke();
  }

  function drawArcText(ctx, text, radius, startAngleDeg, pal, font){
    ctx.save();
    ctx.rotate(startAngleDeg * Math.PI / 180);
    const anglePerChar = 11 * Math.PI / 180;
    for (let i = 0; i < text.length; i++){
      ctx.save();
      ctx.translate(0, -radius);
      embossText(ctx, text[i], 0, 0, font, pal.ink, pal.dark, pal.light, Math.max(1, radius * 0.012));
      ctx.restore();
      ctx.rotate(anglePerChar);
    }
    ctx.restore();
  }

  // ---------- face content ----------

  function drawFrontContent(ctx, w, h, pal){
    const r = Math.min(w, h);
    embossStroke(ctx, function(){
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.82, r * 0.82, 0, 0, Math.PI * 2);
    }, Math.max(2, r * 0.045), pal.ink, pal.dark, pal.light, Math.max(1, r * 0.02));

    embossText(ctx, 'W', 0, -r * 0.04, 'bold ' + Math.max(20, r * 0.62) + 'px Georgia',
      pal.ink, pal.dark, pal.light, Math.max(1, r * 0.025));

    embossText(ctx, 'FINE MINTED COLLECTIBLES', 0, r * 0.48,
      'bold ' + Math.max(6, r * 0.075) + 'px Georgia', pal.ink, pal.dark, pal.light, Math.max(1, r * 0.012));

    drawArcText(ctx, '\u2605 WASTEDTOKEN MINT \u2605', r * 0.68, -125, pal,
      'bold ' + Math.max(8, r * 0.095) + 'px Georgia');
  }

  function drawBackContent(ctx, w, h, pal, denom){
    const r = Math.min(w, h);
    embossStroke(ctx, function(){
      ctx.beginPath();
      ctx.ellipse(0, 0, r * 0.82, r * 0.82, 0, 0, Math.PI * 2);
    }, Math.max(2, r * 0.045), pal.ink, pal.dark, pal.light, Math.max(1, r * 0.02));

    embossText(ctx, denom, 0, -r * 0.1, 'bold ' + Math.max(16, r * 0.42) + 'px Georgia',
      pal.ink, pal.dark, pal.light, Math.max(1, r * 0.02));
    embossText(ctx, 'TOKENS', 0, r * 0.28, 'bold ' + Math.max(10, r * 0.17) + 'px Georgia',
      pal.ink, pal.dark, pal.light, Math.max(1, r * 0.018));

    drawArcText(ctx, '\u2605 LIMITED RESERVE \u2605', r * 0.68, 55, pal,
      'bold ' + Math.max(7, r * 0.08) + 'px Georgia');
  }

  // ---------- edge / reeding ----------

  function drawEdgeOn(ctx, w, h, pal){
    const halfW = Math.max(w, 6);
    ctx.beginPath();
    ctx.ellipse(0, 0, halfW, h, 0, 0, Math.PI * 2);
    const grad = ctx.createLinearGradient(-halfW, 0, halfW, 0);
    grad.addColorStop(0, pal.dark);
    grad.addColorStop(0.35, pal.base);
    grad.addColorStop(0.5, pal.light);
    grad.addColorStop(0.65, pal.base);
    grad.addColorStop(1, pal.dark);
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.save();
    ctx.clip();
    const step = Math.max(2, halfW / 8);
    let idx = 0;
    for (let x = -halfW; x <= halfW; x += step){
      ctx.beginPath();
      ctx.moveTo(x, -h);
      ctx.lineTo(x, h);
      ctx.strokeStyle = (idx % 2 === 0) ? pal.light : pal.dark;
      ctx.globalAlpha = 0.45;
      ctx.lineWidth = 1;
      ctx.stroke();
      idx++;
    }
    ctx.restore();
    ctx.globalAlpha = 1;

    ctx.lineWidth = 1.5;
    ctx.strokeStyle = pal.edge;
    ctx.beginPath();
    ctx.ellipse(0, 0, halfW, h, 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  function drawReedTicks(ctx, w, h, pal){
    const steps = 90;
    for (let i = 0; i < steps; i++){
      const a = (i / steps) * Math.PI * 2;
      const x1 = Math.cos(a) * w * 0.97, y1 = Math.sin(a) * h * 0.97;
      const x2 = Math.cos(a) * w * 1.04, y2 = Math.sin(a) * h * 1.04;
      ctx.strokeStyle = (i % 2 === 0) ? pal.light : pal.dark;
      ctx.globalAlpha = 0.55;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }

  function drawSpecular(ctx, w, h, angleY){
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
    ctx.clip();
    const pos = Math.sin(angleY);
    const bandX = pos * w * 1.3;
    const bandW = Math.max(w * 0.55, 20);
    const grad = ctx.createLinearGradient(bandX - bandW, -h, bandX + bandW, h);
    grad.addColorStop(0, 'rgba(255,255,255,0)');
    grad.addColorStop(0.5, 'rgba(255,255,255,0.6)');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(-w, -h, w * 2, h * 2);
    ctx.restore();
  }

  function drawEdgeRim(ctx, w, h, thickness, pal, scaleX){
    const off = thickness * 0.5 * (scaleX >= 0 ? 1 : -1);
    ctx.beginPath();
    ctx.ellipse(off * 0.35, off * 0.12, w * 1.03, h * 1.03, 0, 0, Math.PI * 2);
    ctx.fillStyle = pal.edge;
    ctx.fill();
  }

  // ---------- master coin renderer ----------
  // Deterministic: output depends only on (t, R, pal, opts).

  const EDGE_THRESH = 0.14;

  function drawCoin(ctx, cx, cy, R, t, pal, opts){
    opts = opts || {};
    const denom = opts.denom || '10,000';

    const angleY = t * Math.PI * 2;
    const angleX = t * Math.PI * 2;
    const scaleX = Math.cos(angleY);
    const absX = Math.max(Math.abs(scaleX), 0.02);
    const scaleY = 0.9 + 0.1 * Math.cos(angleX * 2);
    const wobble = Math.sin(angleX) * 0.05;
    const isFront = scaleX >= 0;
    const thickness = R * 0.16;

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(wobble);

    const w = R * absX;
    const h = R * scaleY;

    if (absX < EDGE_THRESH){
      drawEdgeOn(ctx, w, h, pal);
    } else {
      drawEdgeRim(ctx, w, h, thickness, pal, scaleX);

      ctx.beginPath();
      ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
      const rg = ctx.createRadialGradient(-w * 0.3, -h * 0.3, w * 0.1, 0, 0, Math.max(w, h) * 1.15);
      rg.addColorStop(0, pal.light);
      rg.addColorStop(0.55, pal.base);
      rg.addColorStop(1, pal.dark);
      ctx.fillStyle = rg;
      ctx.fill();

      ctx.save();
      ctx.beginPath();
      ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
      ctx.clip();

      ctx.lineWidth = Math.max(2, w * 0.05);
      ctx.strokeStyle = pal.dark;
      ctx.beginPath();
      ctx.ellipse(0, 0, w * 0.94, h * 0.94, 0, 0, Math.PI * 2);
      ctx.stroke();

      if (isFront){
        drawFrontContent(ctx, w, h, pal);
      } else {
        drawBackContent(ctx, w, h, pal, denom);
      }
      ctx.restore();

      drawReedTicks(ctx, w, h, pal);
      drawSpecular(ctx, w, h, angleY);

      ctx.lineWidth = 2;
      ctx.strokeStyle = pal.edge;
      ctx.beginPath();
      ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  }

  // ---------- palettes ----------

  const PAL = {
    hero:   { base:'#caa15a', light:'#fff6da', dark:'#4a3110', edge:'#2c1c08', ink:'#3a2410' },
    bronze: { base:'#b97a3d', light:'#f6d9a6', dark:'#5c3618', edge:'#3a2410', ink:'#3a2410' },
    silver: { base:'#c9ced3', light:'#ffffff', dark:'#5c6268', edge:'#33383c', ink:'#3f454a' },
    gold:   { base:'#e6b93f', light:'#fff3c4', dark:'#7a5710', edge:'#4a3308', ink:'#5c3f08' },
    black:  { base:'#302f3a', light:'#9d9dc0', dark:'#0a0a0d', edge:'#000000', ink:'#c9c9e8' }
  };

  // ---------- hero ----------

  const heroCanvas = document.getElementById('coin-hero');
  const heroCtx = heroCanvas.getContext('2d');
  const HERO_CX = 300, HERO_CY = 300, HERO_R = 190;
  const LOOP_MS = 6000;

  function paintBackdrop(ctx, w, h){
    ctx.clearRect(0, 0, w, h);
    const bg = ctx.createRadialGradient(w/2, h/2, h*0.1, w/2, h/2, h*0.62);
    bg.addColorStop(0, '#1b1b22');
    bg.addColorStop(1, '#0a0a0d');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);
  }

  function renderHero(t){
    paintBackdrop(heroCtx, heroCanvas.width, heroCanvas.height);
    drawCoin(heroCtx, HERO_CX, HERO_CY, HERO_R, t, PAL.hero, { denom: '10,000' });
  }

  let running = true;
  let rafId = null;
  let startTime = null;

  function frame(now){
    if (startTime === null) startTime = now;
    const elapsed = now - startTime;
    const t = (elapsed / LOOP_MS) % 1;
    renderHero(t);
    if (running) rafId = requestAnimationFrame(frame);
  }

  function play(){
    if (!running){
      running = true;
      startTime = null;
      rafId = requestAnimationFrame(frame);
    }
  }

  function pause(){
    running = false;
    if (rafId !== null){
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  }

  rafId = requestAnimationFrame(frame);

  window.demo = {
    canvas: heroCanvas,
    setTime: function(t){ renderHero(((t % 1) + 1) % 1); },
    pause: pause
  };

  document.getElementById('btn-pause').addEventListener('click', pause);
  document.getElementById('btn-play').addEventListener('click', play);

  // ---------- edition tiles ----------

  function renderEditionCanvas(canvas, pal, state){
    canvas.width = 300;
    canvas.height = 300;
    const ctx = canvas.getContext('2d');
    paintBackdrop(ctx, 300, 300);
    drawCoin(ctx, 150, 150, 108, 0.09, pal, { denom: '10,000' });

    if (state === 'sold-out'){
      ctx.save();
      ctx.globalAlpha = 0.9;
      ctx.translate(150, 150);
      ctx.rotate(-0.26);
      ctx.fillStyle = '#7a1414';
      ctx.fillRect(-150, -22, 300, 44);
      ctx.strokeStyle = '#f2d0d0';
      ctx.lineWidth = 2;
      ctx.strokeRect(-150, -22, 300, 44);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 24px Georgia';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('SOLD OUT', 0, 2);
      ctx.restore();
    }

    if (state === 'coming-soon'){
      ctx.save();
      ctx.globalAlpha = 0.92;
      ctx.translate(150, 150);
      ctx.rotate(-0.26);
      ctx.fillStyle = '#241f4a';
      ctx.fillRect(-155, -22, 310, 44);
      ctx.strokeStyle = '#c9c9e8';
      ctx.lineWidth = 2;
      ctx.strokeRect(-155, -22, 310, 44);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 16px Georgia';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('MINTING WINTER 2026', 0, 2);
      ctx.restore();
    }
  }

  const editionPalettes = { bronze: PAL.bronze, silver: PAL.silver, gold: PAL.gold, black: PAL.black };

  document.querySelectorAll('.edition').forEach(function(tile){
    const key = tile.getAttribute('data-edition');
    const state = tile.getAttribute('data-state');
    const canvas = tile.querySelector('.edition-canvas');
    renderEditionCanvas(canvas, editionPalettes[key], state);
  });

  document.querySelectorAll('button.buy').forEach(function(btn){
    btn.addEventListener('click', function(){
      const original = btn.textContent;
      btn.textContent = 'Added \u2713';
      btn.disabled = true;
      setTimeout(function(){
        btn.textContent = original;
        btn.disabled = false;
      }, 1400);
    });
  });

})();
</script>
</body>
</html>
